-- Fewer, broader presets (13 for spending, 4 for income), each a plain name
-- without "&": Lebensmittel, Restaurants, Transport, Haushalt, Internet,
-- Einkaufen, Gesundheit, Unterhaltung, Reisen, Geschenke, Familie, Finanzen,
-- Sonstiges; Gehalt, Nebenjob, Erstattung, Sonstiges. Each merged preset
-- hands its keywords on, entries move to the new preset and limits of
-- merged presets are added up.

alter table public.categories_presets
  add column kind public.entry_kind not null default 'expense';
comment on column public.categories_presets.kind is
  'Whether the preset is offered for expenses or for income';

on conflict (id) do update set
  group_key = excluded.group_key, names = excluded.names, keywords = excluded.keywords,
  icon = excluded.icon, hue = excluded.hue, peer_average = excluded.peer_average,
  suggested = excluded.suggested, sort_order = excluded.sort_order, kind = excluded.kind;

create temporary table preset_map (old text primary key, new text not null);

update public.entries e set preset_id = m.new from preset_map m where e.preset_id = m.old;

with moved as (
  delete from public.categories_limits l using preset_map m
  where l.preset_id = m.old
  returning l.profile_id, m.new, l.amount
)
select profile_id, new, sum(amount) from moved group by profile_id, new
on conflict (profile_id, category_id, preset_id)
  do update set amount = public.categories_limits.amount + excluded.amount;

delete from public.categories_presets p using preset_map m where p.id = m.old;
drop table preset_map;
